static unsigned char byte(uint64_t at){return(unsigned char)(at^(at>>13)^(at>>23));}
static void size_ok(LIBSSH2_SESSION*s,LIBSSH2_SFTP_HANDLE*h,uint64_t length){LIBSSH2_SFTP_ATTRIBUTES a={0};if(libssh2_sftp_fstat(h,&a)||!(a.flags&LIBSSH2_SFTP_ATTR_SIZE)||a.filesize!=length)fail(s,"size");}
static int cmp(const void*a,const void*b){return strcmp(*(const char*const*)a,*(const char*const*)b);}
int main(int argc,char **argv){
 if(argc!=6)return 2; uint64_t started=now();
