 if(libssh2_session_method_pref(s,LIBSSH2_METHOD_KEX,"curve25519-sha256")||libssh2_session_method_pref(s,LIBSSH2_METHOD_CRYPT_CS,"aes128-ctr")||libssh2_session_method_pref(s,LIBSSH2_METHOD_CRYPT_SC,"aes128-ctr")||libssh2_session_method_pref(s,LIBSSH2_METHOD_MAC_CS,"hmac-sha2-256")||libssh2_session_method_pref(s,LIBSSH2_METHOD_MAC_SC,"hmac-sha2-256"))fail(s,"algorithms");
 if(libssh2_session_handshake(s,fd))fail(s,"handshake");
 size_t keylen=0;int keytype=0;const char *key=libssh2_session_hostkey(s,&keylen,&keytype);if(!key||keytype!=LIBSSH2_HOSTKEY_TYPE_ED25519)fail(s,"hostkey-type");
 LIBSSH2_KNOWNHOSTS *known=libssh2_knownhost_init(s);if(!known)fail(s,"known-init");if(libssh2_knownhost_readfile(known,argv[4],LIBSSH2_KNOWNHOST_FILE_OPENSSH)<0)fail(s,"known-read");struct libssh2_knownhost *matched;
 if(libssh2_knownhost_checkp(known,"127.0.0.1",atoi(argv[1]),key,keylen,LIBSSH2_KNOWNHOST_TYPE_PLAIN|LIBSSH2_KNOWNHOST_KEYENC_RAW|LIBSSH2_KNOWNHOST_KEY_ED25519,&matched)!=LIBSSH2_KNOWNHOST_CHECK_MATCH)fail(s,"hostkey-check");
