 LIBSSH2_SFTP*sf=libssh2_sftp_init(s);if(!sf)fail(s,"sftp-init");LIBSSH2_SFTP_HANDLE*h=libssh2_sftp_opendir(sf,"test");if(!h)fail(s,"opendir");
 libssh2_session_set_blocking(s,0);int flags=fcntl(fd,F_GETFL,0);if(fcntl(fd,F_SETFL,flags|O_NONBLOCK))return 71;
