 while((n=libssh2_sftp_readdir(h,name,sizeof(name),&attrs))==LIBSSH2_ERROR_EAGAIN){if(libssh2_channel_eof(libssh2_sftp_get_channel(sf))){n=LIBSSH2_ERROR_CHANNEL_CLOSED;break;}if(now()-before>200000000){canceled=1;break;}usleep(1000);}
