 if(!strcmp(argv[5],"huge")&&n!=LIBSSH2_ERROR_ALLOC)return 73;
 if(!strcmp(argv[5],"name")&&n!=LIBSSH2_ERROR_BUFFER_TOO_SMALL)return 74;
