 int close_code=libssh2_sftp_close(h);if(close_code==LIBSSH2_ERROR_EAGAIN)return 76;
 int stop_code=libssh2_sftp_shutdown(sf);if(stop_code==LIBSSH2_ERROR_EAGAIN)return 77;
 int free_code=libssh2_session_free(s);if(free_code==LIBSSH2_ERROR_EAGAIN)return 78;
